// First row whose status is not 'done' (or 'failed') is next. The latest 'done' row before it gives continuity.
const rows = $input.all().map(i => i.json).filter(r => r && r.row_number);
const norm = v => String(v ?? '').trim().toLowerCase();
const index = rows.findIndex(r => !['done', 'failed'].includes(norm(r.status)));
if (index === -1) return [{ json: { found: false } }];
const ep = rows[index];
const previous = rows.slice(0, index).filter(r => norm(r.status) === 'done').pop();
return [{ json: {
  found: true,
  row_number: ep.row_number,
  episode: ep.episode || index + 1,
  title: ep.title || '',
  logline: ep.logline || '',
  characters: String(ep.characters || '').split(',').map(s => s.trim()).filter(Boolean),
  previous_title: previous ? (previous.title || '') : '',
  previous_summary: previous ? (previous.summary || '') : 'This is the first episode. Introduce the characters and the world.',
} }];

// Keeps the characters named in this episode (all characters if the column is empty), in that order.
const s = $('Set Film Series Parameters').first().json;
const ep = $('Select Upcoming Episode').first().json;
const all = $('Fetch Character Details').all().map(i => i.json).filter(c => c.name);
const wanted = ep.characters.map(n => n.toLowerCase());
let cast = wanted.length ? wanted.map(n => all.find(c => String(c.name).trim().toLowerCase() === n)).filter(Boolean) : all;
cast = cast.slice(0, Number(s.max_characters));
const missing = cast.filter(c => !/^https?:\/\//.test(String(c.image_url || ''))).map(c => c.name);
if (!cast.length) throw new Error(`Episode ${ep.episode}: no matching characters found in the Characters tab.`);
if (missing.length) throw new Error(`Episode ${ep.episode}: these characters need a public image_url: ${missing.join(', ')}`);
const castText = cast.map((c, i) => `[Image${i + 1}] ${c.name}: ${c.description || 'no description'}`).join('\n');
return [{ json: { image_urls: cast.map(c => c.image_url), cast_names: cast.map(c => c.name), cast_text: castText } }];

