// Replicate input for Seedance 2.5 reference-to-video (schema checked Oct 2026: duration -1 or up to 30 s, up to 30 reference_images, 480p/720p).
// Other models may use different field names: check the model's API tab.
const s = $('Set Film Series Parameters').first().json;
const input = {
  prompt: $json.output.seedance_prompt,
  reference_images: $('Compose Cast List').first().json.image_urls,
  duration: Number(s.duration_seconds),
  resolution: s.resolution,
  aspect_ratio: s.aspect_ratio,
  generate_audio: s.generate_audio === true || s.generate_audio === 'true',
  watermark: false,
  output_format: 'mp4',
};
return [{ json: { model: s.model, body: { input } } }];

// Checks the file before it goes to SocialRobot. Duration comes from the MP4/MOV header (mvhd box).
const s = $('Set Film Series Parameters').first().json;
const item = $input.first();
const video = item.binary && item.binary.data;
const problems = [];
let sizeMb = 0;
let seconds = null;
if (!video) {
  problems.push('No video file was downloaded.');
} else {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  sizeMb = buf.length / 1048576;
  const i = buf.indexOf('mvhd');
  if (i > 3) {
    const v1 = buf[i + 4] === 1;
    const scale = buf.readUInt32BE(i + (v1 ? 24 : 16));
    const units = v1 ? Number(buf.readBigUInt64BE(i + 28)) : buf.readUInt32BE(i + 20);
    if (scale) seconds = Math.round((units / scale) * 10) / 10;
  }
  const type = String(video.mimeType || '');
  if (!/video\/(mp4|quicktime|webm)/.test(type) && !/\.(mp4|mov|webm)$/i.test(video.fileName || '')) problems.push(`Unexpected file type ${type || 'unknown'}.`);
  if (sizeMb > Number(s.max_file_mb)) problems.push(`File is ${sizeMb.toFixed(1)} MB, above the ${s.max_file_mb} MB limit.`);
  if (seconds === null) problems.push('Could not read the video duration.');
  else if (seconds < Number(s.min_seconds) || seconds > Number(s.max_seconds)) problems.push(`Video is ${seconds} s; allowed is ${s.min_seconds}-${s.max_seconds} s.`);
}
return [{
  json: { ok: problems.length === 0, problems, size_mb: Math.round(sizeMb * 100) / 100, duration_seconds: seconds },
  binary: item.binary,
}];

// One readable reason for whatever went wrong.
const j = $json;
const s = $('Set Film Series Parameters').first().json;
let message;
if ($('Abort Long-running Job').isExecuted && j.urls && j.status !== 'failed') {
  message = `Seedance job ${j.id} took longer than ${s.timeout_minutes} minutes and was canceled.`;
} else if (j.status && j.urls) {
  message = `Seedance job ${j.id} ${j.status}: ${j.error || 'no reason given'}`;
} else if (j.error) {
  const e = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
  const step = $('Publish on Threads').isExecuted ? 'Threads' : $('Post Video on Instagram').isExecuted ? 'Instagram Reel' : 'TikTok draft';
  message = `SocialRobot could not publish the ${step}: ${e}`;
} else if (Array.isArray(j.problems) && j.problems.length) {
  message = `The video did not pass the checks: ${j.problems.join(' ')}`;
} else {
  message = `Unexpected failure: ${JSON.stringify(j).slice(0, 500)}`;
}
const ep = $('Select Upcoming Episode').first().json;
return [{ json: { message, row_number: ep.row_number, episode: ep.episode } }];
